Consider this alternative design that avoids the event listener issue entirely:

**Instead of modifying TerminalProcess.continue()**, create a "shadow" monitoring system:

```typescript
class DetachedProcessMonitor {
  // Store original output separately without modifying TerminalProcess behavior
  private captureOutput(process: TerminalProcess): void {
    const originalEmit = process.emit.bind(process)

    // Intercept emits without interfering with normal flow
    process.emit = function(event: string, ...args: any[]) {
      if (event === "line") {
        // Log to file without interfering with normal flow
        logStream.write(args[0] + "\n")
      }
      return originalEmit(event, ...args)
    }
  }
}
```

